import math


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, value in enumerate(a):
        prefix[i + 1] = prefix[i] + value

    def pops_from_lower_hull(o: int, x: int, y: int) -> bool:
        return (x - o) * (prefix[y] - prefix[o]) - (y - o) * (prefix[x] - prefix[o]) <= 0

    def slope_less(i: int, p: int, j: int) -> bool:
        return (prefix[j] - prefix[i]) * (j - p) < (prefix[j] - prefix[p]) * (j - i)

    hull: list[int] = []
    best_num = 0
    best_den = 1
    for right in range(k, n + 1):
        left = right - k
        while len(hull) >= 2 and pops_from_lower_hull(hull[-2], hull[-1], left):
            hull.pop()
        hull.append(left)

        lo = 0
        hi = len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if slope_less(hull[mid], hull[mid + 1], right):
                lo = mid + 1
            else:
                hi = mid
        start = hull[lo]
        num = prefix[right] - prefix[start]
        den = right - start
        if num * best_den > best_num * den:
            best_num = num
            best_den = den

    g = math.gcd(best_num, best_den)
    return [best_num // g, best_den // g]
